select * from jsonb_to_recordset($CITY$[{"ord": 1, "city_id": "vancouver", "author_nickname": "\ud038\uc5d8\ub9ac\uc790\ubca0\uc2a4\uacf5\uc6d0", "tag_slug": "life", "title": "\ubc34\ucfe0\ubc84 \uc0c8 \uc74c\uc218\ub300\uc5d4 \ubb3c\ubcd1 \ucc44\uc6b0\ub294 \uacf3\ub3c4 \ubd99\ub124", "body": "\uc608\uc804\uc5d4 \uae38\uac00 \uc74c\uc218\ub300 \ud558\uba74 \uace0\uac1c \uc219\uc5ec \ub9c8\uc2dc\ub294 \ubaa8\uc591\ubd80\ud130 \ub5a0\uc62c\ub790\ub294\ub370, \uc0c8\ub85c \ub193\ub294 \uac74 \ubb3c\ubcd1 \ucc44\uc6b0\ub294 \uc7a5\uce58\ub3c4 \ubd99\uc74c\n\uae30\uc874 \uc74c\uc218\ub300 \uc911\uc5d4 \uacc4\uc808 \ub530\ub77c \uc26c\ub294 \uac83\ub3c4 \uc788\uc5b4\uc11c, \ubb3c\ubcd1\ub9cc \ub4e4\uace0 \ub098\uac08\uc9c0\ub294 \uc880 \ub354 \uc0dd\uac01 \uc911", "source": "https://vancouver.ca/home-property-development/water-fountains.aspx"}, {"ord": 2, "city_id": "vancouver", "author_nickname": "\uc608\uc77c\ud0c0\uc6b4\ub7f0\uce58", "tag_slug": "life", "title": "\ubcf4\ub4dc \ud0c0\ub294 \uc790\ub9ac\ub3c4 \ubcfc\uacfc \uc2a4\ud2b8\ub9ac\ud2b8\ud615\uc774 \ub2e4\ub974\ub124", "body": "\ubcf4\ub4dc \ud0c0\ub294 \uc0ac\ub78c\ub4e4 \uacf5\uac04\uc744 \ucc98\uc74c \uc54c\uc544\ubcf4\ub2c8 \uacf5\uc6d0\ub9c8\ub2e4 \uc0dd\uae40\uc0c8\ubd80\ud130 \ub2e4\ub984\n\ubc34\ucfe0\ubc84 \uc2a4\ucf00\uc774\ud2b8\ud30c\ud06c\uc5d4 \uc6c0\ud479 \ud30c\uc778 \ubcfc\uc774 \uc788\ub294 \uacf3\ub3c4, \uac70\ub9ac\uc758 \ud131 \uac19\uc740 \uad6c\uc870\ub97c \uc62e\uae34 \uc2a4\ud2b8\ub9ac\ud2b8\ud615\ub3c4 \uc788\uc5b4\n\ub09c \uc77c\ub2e8 \ub450 \ubaa8\uc591 \uad6c\ubd84\ud558\ub294 \uac83\ubd80\ud130 \uc775\ud600\ub450\ub824\uace0, \ub3d9\ub124 \uc9c0\ub3c4\uac00 \ub610 \uc870\uae08 \ub113\uc5b4\uc84c\ub124", "source": "https://vancouver.ca/parks-recreation-culture/skateboard-parks.aspx"}, {"ord": 3, "city_id": "vancouver", "author_nickname": "\ubc84\ub098\ube44\ud638\uc218", "tag_slug": "life", "title": "\uc624\ub798\ub41c \uac74\ubb3c \uc8fc\uc18c\ub85c \ubcf4\ub294 \ubc34\ucfe0\ubc84 \uc720\uc0b0 \ubaa9\ub85d", "body": "\uac74\ubb3c \uad6c\uacbd\ud560 \ub54c \uc774\ub984 \ubab0\ub77c\uc11c \uc544\ub294 \ucc99\ub3c4 \ubabb \ud558\uaca0\uc74c \u314b\u314b \uba54\ubaa8 \ub450 \uac1c \ub0a8\uaca8\ub460\n1) \ubc34\ucfe0\ubc84 \uc720\uc0b0 \ubaa9\ub85d\uc740 \uc2dc\uc758\ud68c\uac00 \uc720\uc0b0 \uac00\uce58\ub97c \uc778\uc815\ud55c \uac74\ubb3c\u00b7\uad6c\uc870\ubb3c\uc744 \ubaa8\uc740 \uac70\uace0\n2) \ub3c4\ub85c \uc8fc\uc18c \uc21c\uc73c\ub85c \uc815\ub9ac\ub3fc \uc788\uc5b4\uc11c \uc775\uc219\ud55c \uae38 \uc774\ub984\ubd80\ud130 \uc77d\uc5b4\ubcf4\uba74 \ub35c \ub0af\uc124 \ub4ef", "source": "https://vancouver.ca/home-property-development/vancouver-heritage-register-vhr.aspx"}, {"ord": 4, "city_id": "vancouver", "author_nickname": "\ub3c4\uc11c\uad00\ub2e8\uace8", "tag_slug": "education", "title": "VPL\uc5d4 \uc18c\ub9ac \ub179\uc74c\ud558\uace0 \uc61b \uc0ac\uc9c4 \uc62e\uae30\ub294 \uacf5\uac04\ub3c4 \uc788\ub124", "body": "\ucc45\uc7a5 \uc0ac\uc774\uc5d0\uc11c \uc870\uc6a9\ud788 \uc77d\ub294 \ubaa8\uc2b5\uc774 \ub3c4\uc11c\uad00\uc758 \uc804\ubd80\ucc98\ub7fc \ub290\uaef4\uc9c0\ub358 \ub54c\uac00 \uc788\uc5c8\ub294\ub370\nVPL \uc778\uc2a4\ud53c\ub808\uc774\uc158 \ub7a9\uc740 \uc18c\ub9ac\u00b7\uc601\uc0c1\u00b7\uc0ac\uc9c4\uc744 \ub9cc\ub4e4\uace0 \ubcf4\uc874\ud558\ub294 \uacf5\uac04\uc774\ub124\n\ub179\uc74c\uc2e4\uc774\ub791 \ub514\uc9c0\ud138 \uc81c\uc791\u00b7\uc790\ub8cc \ubcc0\ud658\uc6a9 \uc791\uc5c5\ub300\uac00 \ud568\uaed8 \uc788\uace0\n\uc13c\ud2b8\ub7f4\ub3c4\uc11c\uad00\ubfd0 \uc544\ub2c8\ub77c \uc2a4\ud2b8\ub798\uc2a4\ucf54\ub098 \ubd84\uad00\uc5d0\ub3c4 \uc774\ub7f0 \uacf5\uac04\uc774 \uc788\uc5b4\n\ub098\ub294 \ubb58 \ub0a8\uaca8\ubcf4\uace0 \uc2f6\uc740\uc9c0\ubd80\ud130 \ucc9c\ucc9c\ud788 \uace8\ub77c\ubcfc\uae4c \ud574", "source": "https://www.vpl.ca/facilities/inspiration-labs"}, {"ord": 5, "city_id": "vancouver", "author_nickname": "\uc2a4\uce74\uc774\ud2b8\ub808\uc778\ud1b5\uadfc", "tag_slug": "transport", "title": "\uc2a4\uce74\uc774\ud2b8\ub808\uc778 \uc5d8\ub9ac\ubca0\uc774\ud130, \uc788\ub294 \uac83\uacfc \uc6b4\ud589 \uc911\uc778 \uac74 \ub2e4\ub984", "body": "\uacc4\ub2e8 \ub300\uc2e0 \uc5d8\ub9ac\ubca0\uc774\ud130\uac00 \ud544\uc694\ud55c \uc0ac\ub78c\ud55c\ud150 \uc5ed \uc785\uad6c\ubd80\ud130 \ub3d9\uc120\uc774 \ub2ec\ub77c\uc9d0\n\uc2a4\uce74\uc774\ud2b8\ub808\uc778\uc740 \ubaa8\ub4e0 \uc5ed\uc5d0 \uc5d8\ub9ac\ubca0\uc774\ud130\uac00 \uc788\uc5b4\n\ub2e4\ub9cc \uc218\ub9ac \uc911\uc77c \uc218\ub3c4 \uc788\uc5b4\uc11c, \uc5ed\uc5d0 \uc788\ub2e4\ub294 \ub9d0\ub9cc\uc73c\ub85c \uadf8\ub0a0 \uc4f8 \uc218 \uc788\ub2e4\uace0 \ubcf4\uba74 \uc548 \ub428\n\uc774\uc6a9 \uc548\ub0b4\ub294 \ubc14\ub014 \uc218 \uc788\uc73c\ub2c8 \ucd9c\ubc1c \uc804\uc5d0 \uc5d8\ub9ac\ubca0\uc774\ud130 \uc6b4\ud589 \uc54c\ub9bc\uc744 \ud655\uc778\ud574\n\ub09c \ub3d9\uc120 \ubcfc \ub54c \uc774\uac78 \uba3c\uc800 \ub123\uc744 \uac70\uc57c", "source": "https://www.translink.ca/opengates"}, {"ord": 6, "city_id": "toronto", "author_nickname": "\ub178\uc2a4\uc695\uc13c\ud130", "tag_slug": "education", "title": "TPL \uc804\ud654 \ub3d9\ud654\uc5d0 \ud55c\uad6d\uc5b4 \uc774\uc57c\uae30\ub3c4 \uc788\ub124", "body": "\ub3d9\ud654\ub3c4 \ud654\uba74\ubd80\ud130 \ucc3e\uc73c\ub824\ub358 \ub098 \uba38\uc4f1 \u314b\u314b\nTPL \ub2e4\uc774\uc5bc\uc5b4\uc2a4\ud1a0\ub9ac\ub294 \uc804\ud654\ub85c \uc774\uc57c\uae30\ub97c \ub4e3\ub294 \uc11c\ube44\uc2a4\uc778\ub370 \ud55c\uad6d\uc5b4\ub3c4 \uc788\uc5b4\uc11c, \uc544\uc774\ub791 \ub4e3\ub294 \ubc29\uc2dd\uc774 \uaf2d \uc601\uc0c1\uc77c \ud544\uc694\ub294 \uc5c6\uc744 \ub4ef", "source": "https://tpl.ca/using-the-library/services/dial-a-story/"}, {"ord": 7, "city_id": "toronto", "author_nickname": "\ube0c\ub7a8\ud134\ucd9c\uadfc", "tag_slug": "transport", "title": "PATH\ub294 \uc9c0\ud558\ucca0 \uc774\ub984\uc774 \uc544\ub2c8\ub77c \uac77\ub294 \uae38\uc774\ub124", "body": "PATH\ub77c\ub294 \uc774\ub984 \ucc98\uc74c \uc775\ud788\ub294 \uc911\uc778\ub370 \uc9c0\ud558\ucca0 \ub178\uc120 \ud558\ub098 \ub354 \uc788\ub294 \uc904 \uc54c\uc558\uc5b4\n\ud1a0\ub860\ud1a0 \ub2e4\uc6b4\ud0c0\uc6b4\uc758 \uc1fc\ud551 \uacf5\uac04\uc774\ub791 \ub300\uc911\uad50\ud1b5\uc744 \uc774\uc5b4\uc8fc\ub294, \uc8fc\ub85c \uc9c0\ud558\uc5d0 \uc788\ub294 \ubcf4\ud589 \ud1b5\ub85c\ub9dd\uc774\ub124\n\ubc16\uc5d0\uc11c\ub9cc \uae38 \ucc3e\ub358 \uba38\ub9bf\uc18d\uc5d0 \uce35 \ud558\ub098 \ub354 \uc0dd\uae34 \ub290\ub08c\uc774\ub77c \uc870\uae08 \uc2e0\uae30\ud568", "source": "https://www.toronto.ca/explore-enjoy/visitor-toronto/getting-around-the-city/"}, {"ord": 8, "city_id": "toronto", "author_nickname": "\uc2a4\uce74\ubcf4\ub85c\ube14\ub7ec\ud504", "tag_slug": "life", "title": "\ud558\uc774\ud30c\ud06c \ub3d9\ubb3c \uc804\uc2dc, 10\uc6d4 13\uc77c\ubd80\ud130 \ud734\uc7a5 \uc608\uc815\uc774\ub124", "body": "\uc544\uc774\ub791 \ub3d9\ubb3c \ubcf4\ub7ec \uac00\ub824\ub294 \uc0ac\ub78c\ub4e4\uc740 \ub2e4\uc74c \uc8fc \uacc4\ud68d\uc774 \ub2ec\ub77c\uc9c8 \uc218\ub3c4 \uc788\uaca0\ub124\n\ud558\uc774\ud30c\ud06c \ub3d9\ubb3c \uc804\uc2dc\ub294 \uc811\uadfc\ub85c \uacf5\uc0ac \ub54c\ubb38\uc5d0 10\uc6d4 13\uc77c\ubd80\ud130 2027\ub144 \ubd04\uae4c\uc9c0 \ub2eb\ub294\ub2e4\uace0 \ub098\uc640 \uc788\uc5b4\n\ub09c \ub2f9\uc7a5 \uc77c\uc815\uc744 \uc815\ud558\uc9c4 \ubabb\ud588\ub294\ub370, \uc774\ucabd \ub300\uc2e0 \uac19\uc774 \ub458\ub7ec\ubcfc \ub9cc\ud55c \uc57c\uc678 \uacf5\uac04\uc740 \uc5b4\ub514\uac00 \uc788\uc744\uae4c?", "source": "https://www.toronto.ca/explore-enjoy/parks-recreation/places-spaces/beaches-gardens-attractions/zoos-farms/high-park-animal-display/"}, {"ord": 9, "city_id": "toronto", "author_nickname": "\ubcbd\ub3cc\uace8\ubaa9\ube5b", "tag_slug": "life", "title": "\ud1a0\ub860\ud1a0 \uacf5\uc6d0 \uc6b4\ub3d9\uae30\uad6c, \uc0b0\ucc45\uc774\ub791 \ubb36\uc5b4\ubcfc \ub9cc\ud558\ub124", "body": "\uc6b4\ub3d9 \uc2dc\uc791\ud558\ub824\ub2c8 \uac70\ucc3d\ud55c \uacc4\ud68d\ubd80\ud130 \uc138\uc6b0\ub294 \uac8c \uc880 \ubd80\ub2f4\uc2a4\ub7ec\uc6cc\uc11c \uc801\uc5b4\ubd04\n1) \ud1a0\ub860\ud1a0\uc5d4 \uc57c\uc678 \uc6b4\ub3d9\uae30\uad6c\uac00 \uc788\ub294 \uacf5\uc6d0\uc774 \ub530\ub85c \uc788\uc5b4\n2) \ub9ac\ubc84\ub370\uc77c \ud30c\ud06c \uc774\uc2a4\ud2b8\ub791 \uc5bc\uc2a4\ucf54\ud2b8 \ud30c\ud06c\ub3c4 \uadf8 \ubaa9\ub85d\uc5d0 \ub4e4\uc5b4\uac00\uace0\n3) \uc774 \uae30\uad6c\ub4e4\uc744 \uc704\ud55c \uc815\uae30 \uc6b4\ub3d9 \uc218\uc5c5\uc774 \uc7a1\ud600 \uc788\ub294 \uac74 \uc544\ub2c8\ub798\n\ub09c \uc0b0\ucc45\uae38\uc5d0 \uac00\uae4c\uc6b4 \uacf3 \ud558\ub098\ubd80\ud130 \uace8\ub77c\ub450\ub824\uace0", "source": "https://www.toronto.ca/explore-enjoy/parks-recreation/program-activities/fitness/outdoor-fitness-equipment/"}, {"ord": 10, "city_id": "toronto", "author_nickname": "\ud1a0\ub860\ud1a0\ub3c4\uc11c\uad00", "tag_slug": "education", "title": "TPL \uc545\uae30 \ub300\uc5ec\ub294 \uc5b4\ub290 \ubd84\uad00\uc778\uc9c0\ub3c4 \ubd10\uc57c\uaca0\ub124", "body": "\uc545\uae30\ub97c \ub35c\ucee5 \uc0ac\uae30 \uc804\uc5d0 \uc7a0\uae50 \uc775\ud600\ubcfc \uc218 \uc788\ub2e4\ub294 \uac8c \uc880 \ubc18\uac00\uc6e0\uc5b4\nTPL\uc5d4 \uae30\ud0c0\u00b7\uc6b0\ucfe8\ub810\ub808\u00b7\ubc14\uc774\uc62c\ub9b0 \uac19\uc740 \uc545\uae30 \ub300\uc5ec \uceec\ub809\uc158\uc774 \uc788\ub124\n\ud604\uc7ac \ud30c\ud06c\ub370\uc77c\u00b7\ub2e4\uc6b4\uc2a4\ubdf0\u00b7\uc694\ud06c\uc6b0\uc988 \ubd84\uad00\uc5d0\uc11c \ub2e4\ub8e8\uace0, \ube4c\ub9b0 \ubd84\uad00\uc73c\ub85c \ub3cc\ub824\uc8fc\ub294 \ubc29\uc2dd\uc774\uc57c\n\ub300\uc5ec \uc808\ucc28\ub294 \ubc14\ub014 \uc218 \uc788\uc73c\ub2c8 \uc2e4\uc81c \uc774\uc6a9 \uc804\uc5d4 \ub2e4\uc2dc \ud655\uc778\ud574\uc57c\uaca0\uc5b4\n\uc544\uc9c1 \ubb58 \uace0\ub97c\uc9c0 \ubaa8\ub974\uaca0\ub294\ub370, \ucc98\uc74c \ubc30\uc6b0\uae30\uc5d4 \uc5b4\ub290 \uc545\uae30\uac00 \ub35c \ub9c9\ub9c9\ud588\uc5b4?", "source": "https://tpl.ca/using-the-library/services/borrow-a-musical-instrument/"}, {"ord": 11, "city_id": "montreal", "author_nickname": "\uc7a5\ud0c8\ub871\ubc14\uad6c\ub2c8", "tag_slug": "life", "title": "\uc559\uadf8\ub9ac\ub1fd \uacf5\uc6d0\uc740 \uc232\uc774\ub791 \ud638\uc218\uac00 \uac19\uc774 \uc788\ub124", "body": "\uc5b4\ub9b4 \ub54c \uacf5\uc6d0 \uadf8\ub9bc \uadf8\ub9ac\uba74 \ub098\ubb34 \uba87 \uadf8\ub8e8\ub9cc \ub123\uc5c8\ub294\ub370, \uc559\uadf8\ub9ac\ub1fd\uc740 \uc232\u00b7\ube48\ud130\u00b7\ud638\uc218\uac00 \ud55c \uacf5\uac04\uc5d0 \uc788\ub124\n\ud55c\ucabd \ud48d\uacbd\ub9cc \ubcf4\ub294 \uc0b0\ucc45\ubcf4\ub2e4 \uc7ac\ubc0c\uc744 \uac83 \uac19\uc544\uc11c, \ub2e4\uc74c\uc5d4 \uac19\uc774 \uac78\uc744 \ud6c4\ubcf4\ub85c \uc5ec\uae30 \ub123\uc5b4\ub450\ub824\uace0", "source": "https://montreal.ca/en/places/parc-angrignon"}, {"ord": 12, "city_id": "montreal", "author_nickname": "\uc62c\ub4dc\ud3ec\ud2b8\ubc14\ub78c", "tag_slug": "life", "title": "\ubaac\ud2b8\ub9ac\uc62c \ub3c4\uc11c\uad00 \uc545\uae30 \ubaa9\ub85d\uc5d4 \ud0c0\uc545\uae30\ub3c4 \uc788\ub124", "body": "\uc624\ub798 \ubd99\ub4e4\uace0 \ubcf4\ub294 \ucc45\ub9cc \ub5a0\uc62c\ub9ac\ub358 \ub3c4\uc11c\uad00\uc5d0 \uc545\uae30 \ubaa9\ub85d\ub3c4 \uc788\ub124\n\ubaac\ud2b8\ub9ac\uc62c \ub3c4\uc11c\uad00 \uc545\uae30 \uceec\ub809\uc158\uc5d4 \uae30\ud0c0\u00b7\uc6b0\ucfe8\ub810\ub808 \uac19\uc740 \ud604\uc545\uae30\ubfd0 \uc544\ub2c8\ub77c \uac74\ubc18\uc774\ub791 \ud0c0\uc545\uae30\ub3c4 \ub4e4\uc5b4\uac00 \uc788\uc5b4\n\ub09c \uc6b0\uc120 \uc545\uae30 \uc774\ub984\ubd80\ud130 \uc775\ud600\ub450\ub824\uace0, \ubc30\uc6b0\uace0 \uc2f6\uc740 \uc18c\ub9ac \uace0\ub974\ub294 \uac83\ubd80\ud130 \uc2dc\uc791\ud574\ub3c4 \ub420 \ub4ef", "source": "https://montreal.ca/en/services/musical-instrument-loans"}, {"ord": 13, "city_id": "montreal", "author_nickname": "\uc62c\ub4dc\ud3ec\ud2b8\ubc14\ub78c", "tag_slug": "life", "title": "\ud504\ub808\ub370\ub9ac\ud06c\ubc31 \uacf5\uc6d0\uc758 \ud770 \uad6c\uccb4, \uac00\uc2a4 \ubaa8\uc73c\ub294 \uc2dc\uc124 \ub36e\uac1c\ub798", "body": "\ud558\uc580 \uad6c\uccb4\uac00 \ub193\uc778 \ud504\ub808\ub370\ub9ac\ud06c\ubc31 \uacf5\uc6d0\uc740 \uc608\uc804\uc5d0 \ucc44\uc11d\uc7a5\uacfc \uc4f0\ub808\uae30 \ub9e4\ub9bd\uc7a5\uc774\ub358 \uacf3\uc774\ub798\n\uadf8 \uad6c\uccb4\uac00 \ub545\uc18d\uc5d0\uc11c \uc0dd\uae30\ub294 \ubc14\uc774\uc624\uac00\uc2a4\ub97c \ubaa8\uc73c\ub294 \uc6b0\ubb3c \ub36e\uac1c\ub77c\ub2c8, \uadf8\ub0e5 \uc7a5\uc2dd\uc740 \uc544\ub2c8\uc5c8\ub124\n\uc5b4\ub9b4 \ub550 \uacf5\uc6d0 \uc2dc\uc124\uc740 \ub180\uc774\uc6a9\ubd80\ud130 \ub5a0\uc62c\ub838\ub294\ub370, \ub2e4\uc74c\uc5d4 \uc774\ub7f0 \uc5ed\ud560\ub3c4 \uac19\uc774 \ubcf4\ub824\uace0", "source": "https://montreal.ca/en/articles/parc-frederic-back-unique-metamorphosis-18997"}, {"ord": 14, "city_id": "montreal", "author_nickname": "\ubd88\uc5b4\ucc45\uac08\ud53c", "tag_slug": "transport", "title": "REV\ub294 \ubaac\ud2b8\ub9ac\uc62c \uc790\uc804\uac70\uae38\ub4e4\uc744 \uc787\ub294 \ud070 \uc904\uae30\ub124", "body": "\uc9c0\ub3c4 \uc0c9\ub9cc \uc678\uc6b0\uba74 \uae38\uc744 \ub2e4 \uc54c \uac83\ucc98\ub7fc \uc0dd\uac01\ud558\ub294 \ubc84\ub987\ubd80\ud130 \uace0\uccd0\uc57c \ud560 \ub4ef \u314b\u314b\nREV\ub294 \ubaac\ud2b8\ub9ac\uc62c \uc790\uc804\uac70\uae38\ub9dd\uc758 \uc911\uc2ec\uc774 \ub418\ub294 \uae09\ud589 \uc790\uc804\uac70 \ub124\ud2b8\uc6cc\ud06c\ub798\n\uac01 \uad6c\uc758 \uc790\uc804\uac70\uae38\uc774 \uc5ec\uae30\uc5d0 \uc5f0\uacb0\ub418\ub294 \uad6c\uc870\uace0, \uc2dc \uc9c0\ub3c4\uc5d0\uc120 \uae38 \uc885\ub958\ub3c4 \ub098\ub220 \ubcfc \uc218 \uc788\uc5b4\n\uaca8\uc6b8\uc5d0\ub3c4 \uc4f0\ub294 \uae38\uc774\uc9c0\ub9cc \uc81c\uc124 \uc911\uc5d4 \uc313\uc778 \ub208 \ub54c\ubb38\uc5d0 \uc77c\ubd80\uac00 \uc881\uc544\uc9c8 \uc218 \uc788\ub300\n\ub09c \ucf54\uc2a4 \ud06c\uac8c \uc7a1\uae30 \uc804\uc5d0 \uac00\uae4c\uc6b4 \uc5f0\uacb0 \uad6c\uac04 \ud558\ub098\ubd80\ud130 \uc54c\uc544\ubcfc\uae4c \ud558\ub294 \uc911", "source": "https://montreal.ca/en/topics/cycling-and-bike-paths"}, {"ord": 15, "city_id": "montreal", "author_nickname": "\ubabd\ub8e8\uc544\uc584\uc78e\uc0c8", "tag_slug": "life", "title": "\ubaac\ud2b8\ub9ac\uc62c \uc9c0\ud558\ub3c4\uc2dc R\u00c9SO, \uc5ed\uacfc \uc1fc\ud551 \uacf5\uac04\uc774 \uc774\uc5b4\uc9c0\ub124", "body": "\uaca8\uc6b8 \ub3d9\uc120 \uc0dd\uac01\ud558\ub2e4\uac00 \uc9c0\ud558\ub3c4\uc2dc R\u00c9SO\ubd80\ud130 \uc0b4\ud3b4\ubcf4\uace0 \uc788\uc5b4\n\ub2e4\uc6b4\ud0c0\uc6b4 \uba54\ud2b8\ub85c\uc5ed\uc774\ub791 \uc1fc\ud551 \uacf5\uac04\uc744 \uc774\uc5b4\uc8fc\ub294 \ubcf4\ud589 \ud1b5\ub85c\ub9dd\uc774\uc57c\n\uac74\ubb3c \ud558\ub098 \uc9c0\ud558\uc0c1\uac00\ub97c \ub9d0\ud558\ub294 \uac8c \uc544\ub2c8\ub77c \uc11c\ub85c \uc5f0\uacb0\ub418\ub294 \uad6c\uc870\ub77c, \ub09c \uc775\uc219\ud55c \uc5ed \uc8fc\ubcc0\ubd80\ud130 \ubcfc \uac70\uc57c\n\ucc98\uc74c \uae38 \uc775\ud790 \ub54c \uc5b4\ub290 \uad6c\uac04\uc774 \ub35c \ud5f7\uac08\ub838\uc5b4?", "source": "https://www.mtl.org/en/experience/guide-underground-city-shopping"}, {"ord": 16, "city_id": "edmonton", "author_nickname": "\ub3d9\ubb3c\uadf8\ub9bc\uc218\ucca9", "tag_slug": "life", "title": "\uc5d0\ub4dc\uba3c\ud134 \uc57c\uc678 \uc6b4\ub3d9\uae30\uad6c, \ub180\uc774\ud130 \uac00\uae4c\uc6b4 \uc790\ub9ac\ub3c4 \uc788\ub124", "body": "\uacf5\uc6d0\uc5d0\uc11c \uc544\uc774 \uc9c0\ucf1c\ubcf4\ub294 \uc0ac\ub78c\ub3c4 \uc6b4\ub3d9\ud560 \uc218 \uc788\uac8c, \uc5d0\ub4dc\uba3c\ud134\uc5d4 \ub180\uc774\ud130 \uac00\uae4c\uc774\uc5d0 \uc6b4\ub3d9\uae30\uad6c\ub97c \ub454 \uacf3\ub4e4\uc774 \uc788\ub124\n\uc608\uc804\uc5d4 \uc5b4\ub978\uc740 \uc606\uc5d0\uc11c \uae30\ub2e4\ub9ac\ub294 \uadf8\ub9bc\ubd80\ud130 \ub5a0\uc62c\ub838\ub294\ub370 \ub0b4 \uc6b4\ub3d9 \ud551\uacc4\uac00 \ud558\ub098 \uc904\uc5b4\ub4e4\uaca0\uad70 \u314b\u314b", "source": "https://www.edmonton.ca/activities_parks_recreation/fitness-parks"}, {"ord": 17, "city_id": "edmonton", "author_nickname": "\uc5d0\ub4dc\uba3c\ud2bc\uaca8\uc6b8", "tag_slug": "life", "title": "\uc61b \uac00\uac8c \ub124\uc628\uc0ac\uc778\uc774 \uc5d0\ub4dc\uba3c\ud134 \uc57c\uc678 \ubc15\ubb3c\uad00\uc5d0 \ub0a8\uc74c", "body": "\ub124\uc628\uc0ac\uc778\ub3c4 \uac00\uac8c \ub2eb\uc73c\uba74 \uadf8\ub0e5 \uc0ac\ub77c\uc9c0\ub294 \uac74 \uc544\ub2cc \ub4ef\n\uc5d0\ub4dc\uba3c\ud134 \ub124\uc628\uc0ac\uc778 \ubc15\ubb3c\uad00\uc5d4 \ubcf5\uc6d0\ud55c \uc61b \uac04\ud310\ub4e4\uc774\n104\uc2a4\ud2b8\ub9ac\ud2b8 \ucabd \uac74\ubb3c \ubc14\uae65 \ubcbd\uc5d0 \ubaa8\uc5ec \uc788\uc74c", "source": "https://www.edmonton.ca/city_government/edmonton_archives/neon-sign-museum"}, {"ord": 18, "city_id": "edmonton", "author_nickname": "\uc81c\uc2a4\ud37c\uc560\ube44\ub274", "tag_slug": "life", "title": "\ub7f0\ub4e4 \uacf5\uc6d0\uc5d0 \uc6d0\ubc18 \ub358\uc9c0\ub294 \ub514\uc2a4\ud06c\uace8\ud504 \ucf54\uc2a4\ub3c4 \uc788\ub124", "body": "\uc6d0\ubc18 \ub358\uc9c0\ub294 \uc0ac\ub78c \ud558\uba74 \ubc18\ub824\uacac \ub180\uc774\ubd80\ud130 \ub5a0\uc62c\ub9b0 \ub0b4\uac00 \ub108\ubb34 \ub2e8\uc21c\ud588\ub098 \ubd04\n\ub7f0\ub4e4 \uacf5\uc6d0\uc5d4 \ub514\uc2a4\ud06c\uace8\ud504 \ucf54\uc2a4\ub3c4 \uc788\uace0, \uc77c\ubc18 \uace8\ud504 \ucf54\uc2a4\ub791\uc740 \ubcc4\ub3c4\ub85c \uc18c\uac1c\ub3fc \uc788\ub124\n\ub09c \uc774\ub984\ubd80\ud130 \ud5f7\uac08\ub9ac\ub294 \ub2e8\uacc4\ub77c \uc5b4\ub290 \ucabd\uc774 \ub9de\uc744\uc9c0\ub294 \uc544\uc9c1 \ubabb \uace0\ub974\uaca0\uc5b4", "source": "https://www.edmonton.ca/activities_parks_recreation/parks_rivervalley/rundle-park"}, {"ord": 19, "city_id": "edmonton", "author_nickname": "\ud5e8\ub370\uc774\ud558\uc774\uc6e8\uc774", "tag_slug": "life", "title": "\ud038\uc5d8\ub9ac\uc790\ubca0\uc2a4 \uacf5\uc6d0 \uc548 \uc6d0\uc8fc\ubbfc \uc608\uc220\uacf5\uc6d0\ub3c4 \uc54c\uc544\uac00\ub294 \uc911", "body": "\uc5d0\ub4dc\uba3c\ud134 \uacf5\uc6d0\uc740 \uc544\uc9c1 \uc775\ud788\ub294 \uc911\uc778\ub370, \uac77\ub294 \uc0ac\ub78c \uc606\uc5d0 \uc791\ud488\uc774 \ub193\uc774\ub294 \uacf5\uac04\ub3c4 \uc788\ub124\n\ud038\uc5d8\ub9ac\uc790\ubca0\uc2a4 \uacf5\uc6d0 \uc548\uc5d0 \u00ceN\u00ceW \ub9ac\ubc84\ub86f11 \uc6d0\uc8fc\ubbfc \uc608\uc220\uacf5\uc6d0\uc774 \uc788\uc5b4\n\uc774 \ub545\uc758 \uc5ed\uc0ac\uc640 \uc774\uc57c\uae30\ub97c \ub2f4\uc740 \uc870\ud615\ubb3c\uc744 \ubc14\uae65 \uc0b0\ucc45\uae38\uc5d0\uc11c \ub9cc\ub098\ub294 \uacf3\uc774\ub798\n\uc9c0\ub3c4\uc5d0\uc11c \uacf5\uc6d0 \uc774\ub984\ub9cc \uc678\uc6b0\ub2e4 \uacf5\ubd80\ud560 \uac8c \ub298\uc5b4\ub0a8 \u314b\u314b \ub2e4\uc74c\uc5d0 \uac19\uc774 \uac78\uc73c\uba74 \uc791\ud488 \uc598\uae30\ub3c4 \ud574\ubcf4\uc790", "source": "https://www.edmonton.ca/activities_parks_recreation/parks_rivervalley/queen-elizabeth-park"}, {"ord": 20, "city_id": "edmonton", "author_nickname": "\ud5e8\ub370\uc774\ud558\uc774\uc6e8\uc774", "tag_slug": "life", "title": "\ubc00\ub108\ub3c4\uc11c\uad00 \ub354\ud0a4\uce5c\uc740 \uc694\ub9ac\ub97c \ubc30\uc6b0\ub294 \uacf5\uac04\uc774\ub124", "body": "\ucc98\uc74c\uc5d4 \ub3c4\uc11c\uad00\uc5d0\uc11c \uc694\ub9ac\ud558\ub294 \uc0ac\ub78c \ub5a0\uc62c\ub9ac\uae30\uac00 \uc880 \uc5b4\ub824\uc6e0\uc74c\n\ubc00\ub108\ub3c4\uc11c\uad00\uc758 \ub354\ud0a4\uce5c\uc740 \uc694\ub9ac\u00b7\ubca0\uc774\ud0b9\u00b7\uc74c\uc2dd\uc744 \ubc30\uc6b0\ub294 \uacf5\uac04\uc774\ub124\n\ucc45\uc5d0\uc11c \uc870\ub9ac\ubc95 \uc77d\ub294 \ub370\uc11c \ub05d\ub098\ub294 \uac8c \uc544\ub2c8\ub77c \uc9c1\uc811 \ubc30\uc6b0\ub294 \ucabd\ub3c4 \uc788\ub294 \uac70\uc57c\n\ub098\ub3c4 \ub3d9\ub124 \uc54c\uc544\uac00\ub294 \uae40\uc5d0 \uc774\ub7f0 \uacf3\ubd80\ud130 \uae30\uc5b5\ud574\ub458\ub798, \uac19\uc774 \uac08 \uc0ac\ub78c\ud55c\ud14c \ub3c4\uc11c\uad00 \uc598\uae30 \uaebc\ub0c8\ub2e4\uac00 \ubc30\uace0\ud30c\uc9c8 \ub4ef \u314b\u314b", "source": "https://www.epl.ca/the-kitchen/"}, {"ord": 21, "city_id": "calgary", "author_nickname": "\ub178\uc2a4\ud790\uc7a5\ubcf4\uae30", "tag_slug": "life", "title": "\ub370\ubcf4\ub2c8\uc548\uac00\ub4e0\uc740 \uac74\ubb3c \uc548\uc5d0\uc11c \uac77\ub294 \uc2dd\ubb3c \uacf5\uac04\uc774\ub124", "body": "\ub370\ubcf4\ub2c8\uc548\uac00\ub4e0 \ucc98\uc74c \uc54c\uc544\ubcf4\ub294\ub370 \uc2e4\ub0b4\uc5d0 \ub098\ubb34\ub791 \uc2dd\ubb3c\uc774 \uc788\uace0 \uc628\ub3c4\ub3c4 \uc870\uc808\ub418\ub294 \uacf5\uac04\uc774\ub124\n\uc1fc\ud551 \uacf5\uac04 \uc704\ucabd\uc5d0 \uc549\uc744 \uc790\ub9ac\ub3c4 \uc788\ub2e4\ub2c8 \uac19\uc774 \uc26c\uae30\uc5d4 \uad1c\ucc2e\uc744 \ub4ef\ud55c\ub370, \uac08 \ub0a0\uc740 \uc544\uc9c1 \ubabb \uc815\ud588\uc5b4", "source": "https://www.calgary.ca/parks/devonian-gardens/features.html"}, {"ord": 22, "city_id": "calgary", "author_nickname": "C\ud2b8\ub808\uc778\ud1b5\uadfc", "tag_slug": "transport", "title": "\ud50c\ub7ec\uc2a415, \uce98\uac70\ub9ac \uac74\ubb3c \uc0ac\uc774\ub97c \uc2e4\ub0b4\ub85c \uac77\ub294 \uae38\uc774\ub124", "body": "\ub2e4\uc6b4\ud0c0\uc6b4 \ud50c\ub7ec\uc2a415\ub294 \uac74\ubb3c \uc0ac\uc774\ub97c \uc787\ub294 \uc9c0\uc0c1 \ubcf4\ud589 \ud1b5\ub85c\ub9dd\uc774\ub77c \ubc14\uae65 \ub0a0\uc528\ub97c \ud53c\ud558\uba70 \uac78\uc744 \uc218 \uc788\uaca0\ub124\n\ub2eb\ud78c \uc5f0\uacb0 \uad6c\uac04\ub3c4 \uc788\uace0 \uc6b4\uc601 \uc548\ub0b4\ub294 \ubc14\ub014 \uc218 \uc788\uc73c\ub2c8, \uc2e4\uc81c \ub3d9\uc120 \uc7a1\uae30 \uc804\uc5d4 \ub2e4\uc2dc \ud655\uc778\ud574\uc57c\uaca0\uc5b4\n\uc544\uc9c1 \uad6c\uc870\uac00 \uba38\ub9bf\uc18d\uc5d0 \uc548 \uc7a1\ud788\ub294\ub370, \ucc98\uc74c \uc774\uc6a9\ud560 \ub54c \uc5b4\ub514\ubd80\ud130 \uc775\ud614\uc5b4?", "source": "https://www.calgary.ca/bike-walk-roll/plus-15-network.html"}, {"ord": 23, "city_id": "calgary", "author_nickname": "\ucee8\ud398\ub354\ub808\uc774\uc158\uacf5\uc6d0", "tag_slug": "life", "title": "\ubca8\ud2b8\ub77c\uc778 \ub85c\uc774\uc2a4\uc790\ubcf4\ucee4\uba3c\uc2a4\uc5d4 \uc57c\uc678 \ud0c1\uad6c\ub300\uac00 \uc788\ub124", "body": "\ud0c1\uad6c\ub294 \uacf5 \uc8fc\uc6b0\ub7ec \ub6f0\ub294 \uc2dc\uac04\uae4c\uc9c0 \uc6b4\ub3d9\uc5d0 \ub123\uc5b4\uc57c \ud560 \uac83 \uac19\uc74c \u314b\u314b\n\ubca8\ud2b8\ub77c\uc778 \ub85c\uc774\uc2a4\uc790\ubcf4\ucee4\uba3c\uc2a4\uc5d0\ub294 \ucf58\ud06c\ub9ac\ud2b8 \ud0c1\uad6c\ub300\ub791 \uc549\uc544\uc11c \uc26c\ub294 \uacf5\uac04\uc774 \uc788\ub124\n\uc2b9\ubd80\ubcf4\ub2e4 \uac00\ubccd\uac8c \uce58\uace0 \uc26c\ub294 \ucabd\uc774 \ub04c\ub9ac\ub294\ub370, \uc774\ub7f0 \uc57c\uc678 \ud0c1\uad6c \uac19\uc774 \ud574\ubcf4\uba74 \uc5b4\ub54c?", "source": "https://www.calgary.ca/parks/lois-szabo-commons.html"}, {"ord": 24, "city_id": "calgary", "author_nickname": "\ubcf4\uc6b0\uac15\ubcc0\uc0b0\ucc45", "tag_slug": "life", "title": "\uba54\ubaa8\ub9ac\uc5bc\ud30c\ud06c\ub3c4\uc11c\uad00\uc5d4 \uc545\uae30 \ub300\uc5ec\ub791 \uc5f0\uc2b5\uc2e4\ub3c4 \uc788\ub124", "body": "\uae30\ud0c0 \ubc30\uc6b0\ub824\uba74 \uc77c\ub2e8 \ub0b4 \uc545\uae30\ubd80\ud130 \uc0ac\uc57c \ud55c\ub2e4\uace0 \uc0dd\uac01\ud588\ub294\ub370\n\uba54\ubaa8\ub9ac\uc5bc\ud30c\ud06c\ub3c4\uc11c\uad00\uc5d4 \uae30\ud0c0\u00b7\uac74\ubc18\u00b7\ud0c0\uc545\uae30 \uac19\uc740 \uc545\uae30\ub97c \ube4c\ub9ac\ub294 \uceec\ub809\uc158\uc774 \uc788\uc74c\n\uc74c\uc545 \uc5f0\uc2b5\uc2e4\ub3c4 \ub530\ub85c \uc788\uc5b4\uc11c \uc545\uae30 \ubaa9\ub85d\uc774\ub791 \uacf5\uac04\uc744 \uac19\uc774 \ubcfc \uc218 \uc788\uc5b4\n\uc608\uc804\uc5d4 \uc545\uae30 \uc774\ub984\ub9cc \uc5f4\uc2ec\ud788 \uc678\uc6e0\ub294\ub370 \uc774\ubc88\uc5d4 \uc18c\ub9ac\ubd80\ud130 \uace8\ub77c\ubcfc \uac70\uc57c, \uc7a5\ubc14\uad6c\ub2c8\ub9cc \uc5f0\uc8fc\ud560 \uc21c \uc5c6\uc796\uc544 \u314b\u314b", "source": "https://www.calgarylibrary.ca/events-and-programs/arts-and-culture/borrow-a-musical-instrument"}, {"ord": 25, "city_id": "calgary", "author_nickname": "\ubcf4\uc6b0\uac15\ubcc0\uc0b0\ucc45", "tag_slug": "life", "title": "\ub784\ud504\ud074\ub77c\uc778\uacf5\uc6d0 \uc2b5\uc9c0\ub294 \ube57\ubb3c\uc744 \ucc98\ub9ac\ud558\ub294 \uacf3\uc774\uae30\ub3c4 \ud568", "body": "\ubb3c\uc740 \uacf5\uc6d0 \ud48d\uacbd\uc778 \uc904\ub9cc \uc54c\uc558\ub294\ub370 \ub784\ud504\ud074\ub77c\uc778\uacf5\uc6d0\uc5d0\uc120 \uc5ed\ud560\uc774 \ub354 \uc788\uc74c\n\uc5ec\uae34 \ube57\ubb3c\uc744 \ucc98\ub9ac\ud558\ub824\uace0 \ub9cc\ub4e0 \uc778\uacf5 \uc2b5\uc9c0 \uc8fc\ubcc0\uc73c\ub85c \uc0b0\ucc45\uae38\uc774 \uc774\uc5b4\uc838\n\uc790\uc5f0\ub180\uc774\ud130\ub3c4 \uc0b0\uc5d0\uc11c \uc2b5\uc9c0\uae4c\uc9c0 \ubb3c\uc774 \uc774\ub3d9\ud558\ub294 \ud750\ub984\uc744 \uc8fc\uc81c\ub85c \ub9cc\ub4e4\uc5c8\ub300\n\uc5b4\ub9b4 \ub54c \ubb3c\uae38 \ub0b8\ub2f5\uc2dc\uace0 \ubaa8\ub798\ub9cc \ud320\ub294\ub370 \uc774\ucabd\uc740 \uc81c\ub300\ub85c \ubb3c \uacf5\ubd80\ud558\ub294 \uacf5\uac04\uc774\ub124 \u314b\u314b\n\ub2e4\uc74c\uc5d4 \uc2dd\ubb3c \uc774\ub984\ub9cc \ubcf4\uc9c0 \ub9d0\uace0 \ubb3c\uc774 \uc5b4\ub514\ub85c \uc774\uc5b4\uc9c0\ub294\uc9c0\ub3c4 \ubcfc \uac70\uc57c", "source": "https://www.calgary.ca/parks/ralph-klein-park-activities.html"}]$CITY$::jsonb) as e(ord int,city_id text,author_nickname text,tag_slug text,title text,body text,source text)
)
select e.ord,p.id,p.city_id,p.title,p.body,p.author_id,p.status,p.created_at,p.posted_on,
 p.created_at at time zone 'America/Vancouver' as created_at_vancouver,
 p.created_at at time zone city.timezone as created_at_city,city.timezone,
 pr.city_id as author_city,pr.nickname as author_nickname,
 u.email like '%@seed.gling.invalid' as seed_account,
 p.comment_count,p.view_count,
 p.body=e.body as body_matches,pr.nickname=e.author_nickname as author_matches,t.slug=e.tag_slug as tag_matches,
 (select count(*) from public.posts same where same.city_id=p.city_id and same.title=p.title and same.status='published') as same_city_title_count,
 (select count(*) from public.posts ap where ap.author_id=p.author_id and ap.status='published') as author_published_post_count,
 (select count(*) from public.comments c where c.post_id=p.id and c.deleted_at is null) as actual_comment_count,
 (select count(*) from public.comments c where c.post_id=p.id and c.deleted_at is null and c.parent_id is null) as root_comment_count,
 (select count(*) from public.comments c where c.post_id=p.id and c.deleted_at is null and c.parent_id is not null) as reply_count,
 (select count(*) from public.comments c where c.post_id=p.id and c.deleted_at is null and c.parent_id is not null and c.author_id=p.author_id) as author_reply_count,
 (select count(*) from public.post_views v where v.post_id=p.id) as real_post_view_rows
from expected e join public.posts p on p.city_id=e.city_id and p.title=e.title and p.status='published'
join public.profiles pr on pr.id=p.author_id join auth.users u on u.id=pr.id
join public.cities city on city.id=p.city_id join public.tags t on t.id=p.tag_id
order by e.ord;
